return [
  {
    json: {
      company_name: "Apple",
      news_url: "https://rss.nytimes.com/services/xml/rss/nyt/Technology.xml"
    }
  },
  {
    json: {
      company_name: "Google",
      news_url: "https://www.theverge.com/rss/index.xml"
    }
  },
  {
    json: {
      company_name: "Microsoft",
      news_url: "https://www.zdnet.com/news/rss.xml"
    }
  },
  {
    json: {
      company_name: "TestCorp-Alarm",
      // Wir geben dem HTTP-Request eine echte URL, damit er nicht abstürzt,
      // aber Gemini wird durch unseren Prompt hier den Alarm auslösen!
      news_url: "https://www.theverge.com/rss/index.xml" 
    }
  }
];

// SCHUTZSCHILD: Prüfen, ob Gemini überhaupt Daten geliefert hat
if (!$input.item.json.content || !$input.item.json.content.parts) {
  return [{ json: { formattedAlarm: "⚠️ Gemini hat für diese Firma keine Daten geliefert (Inhalt leer)." } }];
}

let rawText = $input.item.json.content.parts[0].text;

if (rawText.includes("```json")) {
  rawText = rawText.split("```json")[1].split("```")[0].trim();
} else if (rawText.includes("```")) {
  rawText = rawText.split("```")[1].split("```")[0].trim();
}

let alarmReport = "🚨 **EILMELDUNG: KRITISCHE MARKTVERÄNDERUNG ERKANNT!** 🚨\n";
alarmReport += "=========================================\n\n";

try {
  const data = JSON.parse(rawText);
  alarmReport += `🏢 **FIRMA: ${data.firma.toUpperCase()}**\n`;
  alarmReport += "-----------------------------------------\n";

  for (const insight of data.insights) {
    alarmReport += `🔥 **${insight.titel}** (PRIORITÄT 3)\n`;
    alarmReport += `💡 ${insight.beschreibung}\n\n`;
  }
} catch (e) {
  alarmReport += `⚠️ Parsing-Fehler. Roh-Analyse:\n\n${rawText}`;
}

return [{ json: { formattedAlarm: alarmReport } }];

let finalReport = "🚀 **WÖCHENTLICHER KI-MARKT-REPORT** 🚀\n";
finalReport += "=========================================\n\n";

// Holt alle Elemente, die den Filter erfolgreich überstanden haben
const items = $input.all();

for (const item of items) {
  try {
    // Schutzschild: Falls Gemini mal keine Daten geliefert hat
    if (!item.json.content || !item.json.content.parts) {
      continue; 
    }

    let rawText = item.json.content.parts[0].text;

    if (rawText.includes("```json")) {
      rawText = rawText.split("```json")[1].split("```")[0].trim();
    } else if (rawText.includes("```")) {
      rawText = rawText.split("```")[1].split("```")[0].trim();
    }

    const data = JSON.parse(rawText);

    finalReport += `🏢 **FIRMA: ${data.firma.toUpperCase()}**\n`;
    finalReport += "-----------------------------------------\n";

    for (const insight of data.insights) {
      let emoji = "📌";
      if (insight.dringlichkeit === 2) emoji = "⚠️ [WICHTIG]";

      finalReport += `${emoji} **${insight.titel}**\n`;
      finalReport += `💡 ${insight.beschreibung}\n\n`;
    }
    finalReport += "\n";
  } catch (e) {
    // Fehlerhafte Durchläufe ignorieren
  }
}

return [{ json: { formattedReport: finalReport } }];

